package decision

import (
	"fmt"
	"math"
	"slices"
	"sort"
	"strings"
	"time"

	"github.com/vllm-project/semantic-router/src/semantic-router/pkg/config"
	"github.com/vllm-project/semantic-router/src/semantic-router/pkg/observability/logging"
	"github.com/vllm-project/semantic-router/src/semantic-router/pkg/observability/metrics"
)

// DecisionEngine evaluates routing decisions based on rule combinations
type DecisionEngine struct {
	keywordRules   []config.KeywordRule
	embeddingRules []config.EmbeddingRule
	categories     []config.Category
	decisions      []config.Decision
	strategy       config.RoutingStrategy
	routingScope   config.RecipeName
}

// WithRoutingScope namespaces observability state for recipe-local decision
// names. It does not alter matching or the public DecisionResult.
func (e *DecisionEngine) WithRoutingScope(recipeName config.RecipeName) *DecisionEngine {
	if e != nil {
		e.routingScope = recipeName
	}
	return e
}

// NewDecisionEngine creates a new decision engine
func NewDecisionEngine(
	keywordRules []config.KeywordRule,
	embeddingRules []config.EmbeddingRule,
	categories []config.Category,
	decisions []config.Decision,
	strategy config.RoutingStrategy,
) *DecisionEngine {
	if strategy == "" {
		strategy = config.RoutingStrategyPriority
	}
	return &DecisionEngine{
		keywordRules:   keywordRules,
		embeddingRules: embeddingRules,
		categories:     categories,
		decisions:      decisions,
		strategy:       strategy,
	}
}

// SignalMatches contains all matched signals for decision evaluation
type SignalMatches struct {
	KeywordRules      []string
	EmbeddingRules    []string
	DomainRules       []string
	FactCheckRules    []string // "needs_fact_check" or "no_fact_check_needed"
	UserFeedbackRules []string // "need_clarification", "satisfied", "want_different", "wrong_answer"
	ReaskRules        []string // History-aware dissatisfaction signals from repeated user turns
	PreferenceRules   []string // Route preference names matched via external LLM
	LanguageRules     []string // Language codes: "en", "es", "zh", "fr", etc.
	ContextRules      []string // Context rule names matched (e.g. "low_token_count")
	StructureRules    []string // Structure rule names matched (e.g. "many_questions")
	ComplexityRules   []string // Complexity rules with difficulty level (e.g. "code_complexity:hard")
	ModalityRules     []string // Modality classification: "AR", "DIFFUSION", or "BOTH"
	AuthzRules        []string // Authz rule names matched for user-level routing (e.g. "premium_tier")
	JailbreakRules    []string // Jailbreak rule names matched (confidence >= threshold)
	PIIRules          []string // PII rule names matched (denied PII types detected)
	KBRules           []string // KB signal names matched from global.model_catalog.kbs bindings
	ConversationRules []string // Conversation-shape signal names matched
	EventRules        []string // event rule names (event type, severity, temporal, action codes)
	MetadataRules     []string // untrusted request metadata rule names matched
	ClassifierRules   []string // generic classifier label names matched
	ProjectionRules   []string // Derived routing outputs from routing.projections.mappings

	SignalConfidences map[string]float64 // "signalType:ruleName" → real score (0.0-1.0), e.g. {"embedding:ai": 0.88}. Defaults to 1.0 if missing
	SignalValues      map[string]float64 // raw numeric values exposed by signal evaluators
	SignalErrors      map[string]string  // signal evaluation errors keyed by "type:name"
}

// DecisionResult represents the result of decision evaluation
type DecisionResult struct {
	Decision        *config.Decision
	Confidence      float64
	MatchedRules    []string
	MatchedKeywords []string // The actual keywords that matched (not rule names)
}

// EvaluateDecisions evaluates all decisions and returns the best match based on strategy
// matchedKeywordRules: list of matched keyword rule names
// matchedEmbeddingRules: list of matched embedding rule names
// matchedDomainRules: list of matched domain rule names (category names)
func (e *DecisionEngine) EvaluateDecisions(
	matchedKeywordRules []string,
	matchedEmbeddingRules []string,
	matchedDomainRules []string,
) (*DecisionResult, error) {
	// Call EvaluateDecisionsWithSignals with empty fact_check rules for backward compatibility
	return e.EvaluateDecisionsWithSignals(&SignalMatches{
		KeywordRules:   matchedKeywordRules,
		EmbeddingRules: matchedEmbeddingRules,
		DomainRules:    matchedDomainRules,
		FactCheckRules: nil,
	})
}

// EvaluateDecisionsWithSignals evaluates all decisions using SignalMatches
// This is the new method that supports all signal types including fact_check
func (e *DecisionEngine) EvaluateDecisionsWithSignals(signals *SignalMatches) (*DecisionResult, error) {
	// Record decision evaluation start time
	start := time.Now()
	defer func() {
		latencySeconds := time.Since(start).Seconds()
		metrics.RecordDecisionEvaluation(latencySeconds)
	}()

	if len(e.decisions) == 0 {
		return nil, fmt.Errorf("no decisions configured")
	}

	var results []DecisionResult

	// Evaluate each decision
	for i := range e.decisions {
		decision := &e.decisions[i]
		matched, confidence, matchedRules := e.evaluateDecisionWithSignals(decision, signals)

		if matched {
			// Record decision match with confidence
			metrics.RecordDecisionMatch(config.RoutingDecisionKey(e.routingScope, decision.Name), confidence)

			results = append(results, DecisionResult{
				Decision:     decision,
				Confidence:   confidence,
				MatchedRules: matchedRules,
			})
		}
	}

	if len(results) == 0 {
		logging.Infof("No decision matched")
		return nil, nil
	}

	// Select best decision based on strategy
	return e.selectBestDecision(results), nil
}

// evaluateDecisionWithSignals evaluates a single decision's rule tree with all signals.
func (e *DecisionEngine) evaluateDecisionWithSignals(
	decision *config.Decision,
	signals *SignalMatches,
) (matched bool, confidence float64, matchedRules []string) {
	// Omitting rules is the YAML equivalent of a DSL route without WHEN. Keep
	// this root-only contract explicit instead of relying on the zero value to
	// fall through to OR semantics.
	if decision.Rules.IsEmpty() {
		return true, 0, nil
	}
	return e.evalNode(decision.Rules, signals)
}

// evalNode recursively evaluates a RuleNode (boolean expression tree) against signal matches.
// Leaf nodes check whether a specific named signal is present.
// Composite nodes apply AND / OR / NOT logic over their children.
func (e *DecisionEngine) evalNode(
	node config.RuleNode,
	signals *SignalMatches,
) (matched bool, confidence float64, matchedRules []string) {
	if node.IsLeaf() {
		return e.evalLeaf(node, signals)
	}

	switch strings.ToUpper(node.Operator) {
	case "AND":
		return e.evalAND(node.Conditions, signals)
	case "NOT":
		return e.evalNOT(node.Conditions, signals)
	default: // OR
		return e.evalOR(node.Conditions, signals)
	}
}

// evalLeaf evaluates a single signal condition (leaf node).
func (e *DecisionEngine) evalLeaf(
	node config.RuleNode,
	signals *SignalMatches,
) (matched bool, confidence float64, matchedRules []string) {
	normalizedType := strings.ToLower(strings.TrimSpace(node.Type))

	matched, supported := e.matchesSignalType(normalizedType, node.Name, signals)
	if !supported {
		return false, 0, nil
	}
	if node.Predicate != nil {
		return evaluatePredicateLeaf(node, normalizedType, signals)
	}
	if !matched {
		return false, 0, nil
	}

	confidence = signalConfidence(signals.SignalConfidences, normalizedType, node.Name)
	return true, confidence, []string{formatMatchedRule(node)}
}

func evaluatePredicateLeaf(
	node config.RuleNode,
	normalizedType string,
	signals *SignalMatches,
) (bool, float64, []string) {
	value, available := signalPredicateValue(signals, normalizedType, node.Name, node.Label)
	if available {
		if numericPredicateMatches(value, node.Predicate) {
			return true, 1.0, []string{formatMatchedRule(node)}
		}
		return false, 0, nil
	}
	errorKey := fmt.Sprintf("%s:%s", normalizedType, node.Name)
	_, failed := signals.SignalErrors[errorKey]
	if failed && strings.EqualFold(strings.TrimSpace(node.OnError), "match") {
		return true, 1.0, []string{formatMatchedRule(node)}
	}
	return false, 0, nil
}

func formatMatchedRule(node config.RuleNode) string {
	rule := fmt.Sprintf("%s:%s", node.Type, node.Name)
	if node.Label != "" {
		rule += ":" + node.Label
	}
	return rule
}

func signalPredicateValue(
	signals *SignalMatches,
	signalType string,
	name string,
	label string,
) (float64, bool) {
	key := fmt.Sprintf("%s:%s", signalType, name)
	if label != "" {
		key += ":" + label
	}
	if signals.SignalValues != nil {
		if value, ok := signals.SignalValues[key]; ok {
			return value, true
		}
	}
	if signals.SignalConfidences != nil {
		value, ok := signals.SignalConfidences[key]
		return value, ok
	}
	return 0, false
}

func numericPredicateMatches(value float64, predicate *config.NumericPredicate) bool {
	if predicate == nil {
		return true
	}
	if math.IsNaN(value) || math.IsInf(value, 0) {
		return false
	}
	if predicate.GT != nil && value <= *predicate.GT {
		return false
	}
	if predicate.GTE != nil && value < *predicate.GTE {
		return false
	}
	if predicate.LT != nil && value >= *predicate.LT {
		return false
	}
	if predicate.LTE != nil && value > *predicate.LTE {
		return false
	}
	return true
}

func (e *DecisionEngine) matchesSignalType(
	normalizedType string,
	name string,
	signals *SignalMatches,
) (matched bool, supported bool) {
	if normalizedType == "domain" {
		return e.matchesDomainCondition(name, signals.DomainRules), true
	}
	if normalizedType == config.SignalTypeClassifier {
		// Classifier conditions are predicate-only and configuration validation
		// guarantees that the named classifier exists.
		return false, true
	}

	rules, ok := resolveSignalRules(normalizedType, signals)
	if !ok {
		return false, false
	}
	return slices.Contains(rules, name), true
}

func resolveSignalRules(
	signalType string,
	signals *SignalMatches,
) ([]string, bool) {
	if rules, ok := resolvePrimarySignalRules(signalType, signals); ok {
		return rules, true
	}
	return resolvePolicySignalRules(signalType, signals)
}

func resolvePrimarySignalRules(
	signalType string,
	signals *SignalMatches,
) ([]string, bool) {
	switch signalType {
	case config.SignalTypeKeyword:
		return signals.KeywordRules, true
	case config.SignalTypeEmbedding:
		return signals.EmbeddingRules, true
	case config.SignalTypeFactCheck:
		return signals.FactCheckRules, true
	case config.SignalTypeUserFeedback:
		return signals.UserFeedbackRules, true
	case config.SignalTypeReask:
		return signals.ReaskRules, true
	case config.SignalTypePreference:
		return signals.PreferenceRules, true
	case config.SignalTypeLanguage:
		return signals.LanguageRules, true
	case config.SignalTypeContext:
		return signals.ContextRules, true
	case config.SignalTypeStructure:
		return signals.StructureRules, true
	case config.SignalTypeComplexity:
		return signals.ComplexityRules, true
	default:
		return nil, false
	}
}

func resolvePolicySignalRules(
	signalType string,
	signals *SignalMatches,
) ([]string, bool) {
	switch signalType {
	case config.SignalTypeModality:
		return signals.ModalityRules, true
	case config.SignalTypeAuthz:
		return signals.AuthzRules, true
	case config.SignalTypeJailbreak:
		return signals.JailbreakRules, true
	case config.SignalTypePII:
		return signals.PIIRules, true
	case config.SignalTypeKB:
		return signals.KBRules, true
	case config.SignalTypeConversation:
		return signals.ConversationRules, true
	case config.SignalTypeEvent:
		return signals.EventRules, true
	case config.SignalTypeMetadata:
		return signals.MetadataRules, true
	case config.SignalTypeProjection:
		return signals.ProjectionRules, true
	default:
		return nil, false
	}
}

func signalConfidence(confidences map[string]float64, signalType string, name string) float64 {
	if confidences == nil {
		return 1.0
	}

	signalKey := fmt.Sprintf("%s:%s", signalType, name)
	if score, ok := confidences[signalKey]; ok {
		return score
	}
	return 1.0
}

// evalAND returns true only when every child matches.
// An empty conjunction acts as a catch-all/default route with zero confidence,
// so it can serve as a fallback without outranking signal-backed decisions when
// confidence-based selection is enabled.
func (e *DecisionEngine) evalAND(
	children []config.RuleNode,
	signals *SignalMatches,
) (matched bool, confidence float64, matchedRules []string) {
	if len(children) == 0 {
		return true, 0, nil
	}
	totalConf := 0.0
	for _, child := range children {
		m, c, r := e.evalNode(child, signals)
		if !m {
			return false, 0, nil
		}
		totalConf += c
		matchedRules = append(matchedRules, r...)
	}
	return true, totalConf / float64(len(children)), matchedRules
}

// evalOR returns true when at least one child matches; returns the best-confidence match.
func (e *DecisionEngine) evalOR(
	children []config.RuleNode,
	signals *SignalMatches,
) (matched bool, confidence float64, matchedRules []string) {
	bestConf := 0.0
	var bestRules []string
	for _, child := range children {
		m, c, r := e.evalNode(child, signals)
		if m && (!matched || c > bestConf) {
			matched = true
			bestConf = c
			bestRules = r
		}
	}
	if matched {
		return true, bestConf, bestRules
	}
	return false, 0, nil
}

// evalNOT is a strictly unary operator: it negates the result of its single child.
// Configuration errors (0 or 2+ children) are treated as non-matching.
func (e *DecisionEngine) evalNOT(
	children []config.RuleNode,
	signals *SignalMatches,
) (matched bool, confidence float64, matchedRules []string) {
	if len(children) != 1 {
		logging.Warnf("NOT operator requires exactly 1 child, got %d — treating as non-match", len(children))
		return false, 0, nil
	}
	m, c, r := e.evalNode(children[0], signals)
	if !m {
		// Child did not match → NOT matches with full certainty.
		return true, 1.0, r
	}
	// Child matched → NOT does not match.
	return false, c, r
}

// matchesDomainCondition checks if any of the detected domains match the given category name
// A match occurs if:
// 1. The detected domain equals the category name directly, OR
// 2. The detected domain is in the category's mmlu_categories list
func (e *DecisionEngine) matchesDomainCondition(categoryName string, detectedDomains []string) bool {
	// Direct match: detected domain equals the category name
	if slices.Contains(detectedDomains, categoryName) {
		return true
	}

	// Check if any detected domain is in the category's mmlu_categories
	for _, cat := range e.categories {
		if cat.Name == categoryName {
			for _, detectedDomain := range detectedDomains {
				if slices.Contains(cat.MMLUCategories, detectedDomain) {
					return true
				}
			}
			break // Found the category, no need to continue
		}
	}
	return false
}

// selectBestDecision selects the best decision based on the configured strategy
func (e *DecisionEngine) selectBestDecision(results []DecisionResult) *DecisionResult {
	if len(results) == 0 {
		return nil
	}

	if len(results) == 1 {
		return &results[0]
	}

	useTieredSelection := e.useTieredSelection(results)
	sort.Slice(results, func(i, j int) bool {
		return e.decisionResultLess(results[i], results[j], useTieredSelection)
	})

	return &results[0]
}

func (e *DecisionEngine) useTieredSelection(results []DecisionResult) bool {
	for _, result := range results {
		if result.Decision != nil && result.Decision.Tier > 0 {
			return true
		}
	}
	return false
}

func (e *DecisionEngine) decisionResultLess(
	left DecisionResult,
	right DecisionResult,
	useTieredSelection bool,
) bool {
	if useTieredSelection {
		if left.Decision.Tier != right.Decision.Tier {
			return left.Decision.Tier < right.Decision.Tier
		}
		if left.Confidence != right.Confidence {
			return left.Confidence > right.Confidence
		}
		if left.Decision.Priority != right.Decision.Priority {
			return left.Decision.Priority > right.Decision.Priority
		}
		return left.Decision.Name < right.Decision.Name
	}

	if e.strategy == config.RoutingStrategyConfidence {
		if left.Confidence != right.Confidence {
			return left.Confidence > right.Confidence
		}
		if left.Decision.Priority != right.Decision.Priority {
			return left.Decision.Priority > right.Decision.Priority
		}
		return left.Decision.Name < right.Decision.Name
	}

	if left.Decision.Priority != right.Decision.Priority {
		return left.Decision.Priority > right.Decision.Priority
	}
	if left.Confidence != right.Confidence {
		return left.Confidence > right.Confidence
	}
	return left.Decision.Name < right.Decision.Name
}

package extproc

import (
	"encoding/json"
	"strings"

	"github.com/vllm-project/semantic-router/src/semantic-router/pkg/classification"
	"github.com/vllm-project/semantic-router/src/semantic-router/pkg/config"
	"github.com/vllm-project/semantic-router/src/semantic-router/pkg/observability/logging"
	"github.com/vllm-project/semantic-router/src/semantic-router/pkg/projectiontrace"
	"github.com/vllm-project/semantic-router/src/semantic-router/pkg/promptcompression"
)

type signalEvaluationInput struct {
	evaluationText         string
	allMessagesText        string
	compressedText         string
	skipCompressionSignals map[string]bool
	currentUserText        string
	priorUserMessages      []string
	hasAssistantReply      bool
	conversationFacts      classification.ConversationFacts
	requestFacts           classification.RequestFacts
}

func (r *OpenAIRouter) prepareSignalEvaluationInput(history signalConversationHistory) signalEvaluationInput {
	input := signalEvaluationInput{
		evaluationText:    history.currentUserMessage,
		compressedText:    history.currentUserMessage,
		allMessagesText:   strings.Join(history.nonUserMessages, " "),
		currentUserText:   history.currentUserMessage,
		priorUserMessages: append([]string(nil), history.priorUserMessages...),
		hasAssistantReply: history.hasAssistantReply,
		conversationFacts: classification.ConversationFacts{
			HasDeveloperMessage:     history.hasDeveloperMessage,
			UserMessageCount:        history.userMessageCount,
			AssistantMessageCount:   history.assistantMessageCount,
			SystemMessageCount:      history.systemMessageCount,
			ToolMessageCount:        history.toolMessageCount,
			ToolDefinitionCount:     history.toolDefinitionCount,
			AssistantToolCallCount:  history.assistantToolCallCount,
			ToolResultCount:         history.toolResultCount,
			ImageContentCount:       history.imageContentCount,
			LastMessageRole:         history.lastMessageRole,
			LastMessageToolResult:   history.lastMessageToolResult,
			LastUserAfterToolResult: history.lastUserAfterToolResult,
		},
		requestFacts: classification.RequestFacts{
			Metadata: cloneRoutingMetadata(history.metadata),
		},
	}

	if input.evaluationText == "" && len(history.nonUserMessages) > 0 {
		input.evaluationText = strings.Join(history.nonUserMessages, " ")
		input.compressedText = input.evaluationText
	}

	if history.currentUserMessage != "" && len(history.nonUserMessages) > 0 {
		allMessages := make([]string, 0, len(history.nonUserMessages)+1)
		allMessages = append(allMessages, history.nonUserMessages...)
		allMessages = append(allMessages, history.currentUserMessage)
		input.allMessagesText = strings.Join(allMessages, " ")
	} else if history.currentUserMessage != "" {
		input.allMessagesText = history.currentUserMessage
	}

	if input.evaluationText == "" {
		return input
	}

	input.compressedText, input.skipCompressionSignals = r.compressSignalEvaluationText(input.evaluationText)
	return input
}

func (r *OpenAIRouter) compressSignalEvaluationText(evaluationText string) (string, map[string]bool) {
	compressedText := evaluationText
	var skipCompressionSignals map[string]bool

	if !r.Config.PromptCompression.Enabled || r.Config.PromptCompression.MaxTokens <= 0 {
		return compressedText, skipCompressionSignals
	}

	cfg := buildCompressionConfig(r.Config.PromptCompression)
	origTokens := promptcompression.CountTokensApprox(evaluationText)
	if r.Config.PromptCompression.MinLength > 0 && len(evaluationText) <= r.Config.PromptCompression.MinLength {
		logging.Infof("[PromptCompression] Skipped: %d chars <= min_length threshold %d", len(evaluationText), r.Config.PromptCompression.MinLength)
		return compressedText, skipCompressionSignals
	}
	if origTokens <= cfg.MaxTokens {
		return compressedText, skipCompressionSignals
	}

	result := promptcompression.Compress(evaluationText, cfg)
	logging.Infof("[PromptCompression] Compressed evaluationText: %d -> %d tokens (ratio=%.2f, kept %d sentences)",
		result.OriginalTokens, result.CompressedTokens, result.Ratio, len(result.KeptIndices))
	return result.Compressed, r.Config.PromptCompression.SkipSignalsSet()
}

func (r *OpenAIRouter) applySignalResultsToContext(ctx *RequestContext, signals *classification.SignalResults) {
	ctx.VSRMatchedKeywords = signals.MatchedKeywordRules
	ctx.VSRMatchedEmbeddings = signals.MatchedEmbeddingRules
	ctx.VSRMatchedDomains = signals.MatchedDomainRules
	ctx.VSRMatchedFactCheck = signals.MatchedFactCheckRules
	ctx.VSRMatchedUserFeedback = signals.MatchedUserFeedbackRules
	ctx.VSRMatchedReask = signals.MatchedReaskRules
	ctx.VSRMatchedPreference = signals.MatchedPreferenceRules
	ctx.VSRMatchedLanguage = signals.MatchedLanguageRules
	ctx.VSRMatchedContext = signals.MatchedContextRules
	ctx.VSRContextTokenCount = signals.TokenCount
	ctx.VSRMatchedStructure = signals.MatchedStructureRules
	ctx.VSRMatchedComplexity = signals.MatchedComplexityRules
	ctx.VSRMatchedModality = signals.MatchedModalityRules
	ctx.VSRMatchedAuthz = signals.MatchedAuthzRules
	ctx.VSRMatchedJailbreak = signals.MatchedJailbreakRules
	ctx.VSRMatchedPII = signals.MatchedPIIRules
	ctx.VSRMatchedKB = signals.MatchedKBRules
	ctx.VSRMatchedConversation = signals.MatchedConversationRules
	ctx.VSRMatchedEvent = signals.MatchedEventRules
	ctx.VSRMatchedMetadata = signals.MatchedMetadataRules
	ctx.VSRMatchedClassifier = signals.MatchedClassifierRules
	ctx.VSRMatchedProjection = signals.MatchedProjectionRules
	ctx.VSRProjectionScores = cloneReplayFloat64Map(signals.ProjectionScores)
	ctx.VSRSignalConfidences = cloneReplayFloat64Map(signals.SignalConfidences)
	ctx.VSRSignalValues = cloneReplayFloat64Map(signals.SignalValues)
	ctx.VSRSignalErrors = cloneReplayStringMap(signals.SignalErrors)
	ctx.VSRProjectionTrace = cloneProjectionTraceForReplay(signals.ProjectionTrace)

	if signals.JailbreakDetected {
		ctx.JailbreakDetected = signals.JailbreakDetected
		ctx.JailbreakType = signals.JailbreakType
		ctx.JailbreakConfidence = signals.JailbreakConfidence
	}
	if signals.PIIDetected {
		ctx.PIIDetected = signals.PIIDetected
		ctx.PIIEntities = signals.PIIEntities
	}

	r.setFactCheckFromSignals(ctx, signals.MatchedFactCheckRules)
	r.setModalityFromSignals(ctx, signals.MatchedModalityRules)
}

func cloneProjectionTraceForReplay(t *projectiontrace.Trace) *projectiontrace.Trace {
	if t == nil {
		return nil
	}
	b, err := json.Marshal(t)
	if err != nil {
		logging.Warnf("failed to clone projection trace for replay during marshal: %v", err)
		return nil
	}
	var out projectiontrace.Trace
	if err := json.Unmarshal(b, &out); err != nil {
		logging.Warnf("failed to clone projection trace for replay during unmarshal: %v", err)
		return nil
	}
	return &out
}

func cloneReplayFloat64Map(values map[string]float64) map[string]float64 {
	if values == nil {
		return nil
	}
	cloned := make(map[string]float64, len(values))
	for key, value := range values {
		cloned[key] = value
	}
	return cloned
}

func cloneReplayStringMap(values map[string]string) map[string]string {
	if values == nil {
		return nil
	}
	cloned := make(map[string]string, len(values))
	for key, value := range values {
		cloned[key] = value
	}
	return cloned
}

func collectMatchedSignalRules(signals *classification.SignalResults) []string {
	allMatchedRules := []string{}
	allMatchedRules = append(allMatchedRules, signals.MatchedKeywordRules...)
	allMatchedRules = append(allMatchedRules, signals.MatchedEmbeddingRules...)
	allMatchedRules = append(allMatchedRules, signals.MatchedDomainRules...)
	allMatchedRules = append(allMatchedRules, signals.MatchedFactCheckRules...)
	allMatchedRules = append(allMatchedRules, signals.MatchedUserFeedbackRules...)
	allMatchedRules = append(allMatchedRules, signals.MatchedReaskRules...)
	allMatchedRules = append(allMatchedRules, signals.MatchedPreferenceRules...)
	allMatchedRules = append(allMatchedRules, signals.MatchedLanguageRules...)
	allMatchedRules = append(allMatchedRules, signals.MatchedContextRules...)
	allMatchedRules = append(allMatchedRules, signals.MatchedStructureRules...)
	allMatchedRules = append(allMatchedRules, signals.MatchedComplexityRules...)
	allMatchedRules = append(allMatchedRules, signals.MatchedModalityRules...)
	allMatchedRules = append(allMatchedRules, signals.MatchedAuthzRules...)
	allMatchedRules = append(allMatchedRules, signals.MatchedJailbreakRules...)
	allMatchedRules = append(allMatchedRules, signals.MatchedPIIRules...)
	allMatchedRules = append(allMatchedRules, signals.MatchedKBRules...)
	allMatchedRules = append(allMatchedRules, signals.MatchedConversationRules...)
	allMatchedRules = append(allMatchedRules, signals.MatchedEventRules...)
	allMatchedRules = append(allMatchedRules, signals.MatchedMetadataRules...)
	allMatchedRules = append(allMatchedRules, signals.MatchedClassifierRules...)
	allMatchedRules = append(allMatchedRules, signals.MatchedProjectionRules...)
	return allMatchedRules
}

// buildCompressionConfig translates the YAML config into the promptcompression
// package's Config struct, applying defaults for omitted fields.
func buildCompressionConfig(pc config.PromptCompressionConfig) promptcompression.Config {
	cfg := promptcompression.ProfileConfig(pc.NormalizedProfile(), pc.MaxTokens)
	if pc.TextRankWeight > 0 {
		cfg.TextRankWeight = pc.TextRankWeight
	}
	if pc.PositionWeight > 0 {
		cfg.PositionWeight = pc.PositionWeight
	}
	if pc.TFIDFWeight > 0 {
		cfg.TFIDFWeight = pc.TFIDFWeight
	}
	if pc.NoveltyWeight > 0 {
		cfg.NoveltyWeight = pc.NoveltyWeight
	}
	if pc.PositionDepth > 0 {
		cfg.PositionDepth = pc.PositionDepth
	}
	if pc.PreserveFirstN > 0 {
		cfg.PreserveFirstN = pc.PreserveFirstN
	}
	if pc.PreserveLastN > 0 {
		cfg.PreserveLastN = pc.PreserveLastN
	}
	return cfg
}

package extproc

import (
	"fmt"
	"strings"
	"time"

	"github.com/vllm-project/semantic-router/src/semantic-router/pkg/classification"
	"github.com/vllm-project/semantic-router/src/semantic-router/pkg/config"
	"github.com/vllm-project/semantic-router/src/semantic-router/pkg/decision"
	"github.com/vllm-project/semantic-router/src/semantic-router/pkg/observability/logging"
	"github.com/vllm-project/semantic-router/src/semantic-router/pkg/observability/tracing"
	"github.com/vllm-project/semantic-router/src/semantic-router/pkg/selection"
	"github.com/vllm-project/semantic-router/src/semantic-router/pkg/utils/entropy"
)

var selectionMethodByAlgorithmType = map[string]selection.SelectionMethod{
	"router_dc":     selection.MethodRouterDC,
	"automix":       selection.MethodAutoMix,
	"hybrid":        selection.MethodHybrid,
	"latency_aware": selection.MethodLatencyAware,
	"static":        selection.MethodStatic,
	"knn":           selection.MethodKNN,
	"kmeans":        selection.MethodKMeans,
	"svm":           selection.MethodSVM,
	"multi_factor":  selection.MethodMultiFactor,
	"mlp":           selection.MethodMLP,
	"prompt":        selection.MethodPrompt,
}

func (r *OpenAIRouter) evaluateSignalsForDecision(
	originalModel string,
	signalInput signalEvaluationInput,
	nonUserMessages []string,
	ctx *RequestContext,
	candidates []config.Decision,
) (*classification.SignalResults, error) {
	signalStart := time.Now()
	signalCtx, signalSpan := tracing.StartSpan(ctx.TraceContext, tracing.SpanSignalEvaluation)

	classifier := r.classifierForRequest(ctx)
	if classifier == nil {
		return nil, fmt.Errorf("classifier for routing recipe %q is unavailable", ctx.Routing.RecipeName())
	}

	signals, authzErr := classifier.EvaluateAllSignalsWithHeaders(classification.SignalEvaluationInput{
		Text:                   signalInput.compressedText,
		ContextText:            signalInput.allMessagesText,
		CurrentUserText:        signalInput.currentUserText,
		PriorUserMessages:      signalInput.priorUserMessages,
		NonUserMessages:        nonUserMessages,
		HasPriorAssistantReply: signalInput.hasAssistantReply,
		Headers:                ctx.Headers,
		ImageURL:               ctx.RequestImageURL,
		UncompressedText:       signalInput.evaluationText,
		SkipCompressionSignals: signalInput.skipCompressionSignals,
		ConversationFacts:      signalInput.conversationFacts,
		RequestFacts:           signalInput.requestFacts,
	})
	if authzErr != nil {
		signalSpan.End()
		logging.ComponentErrorEvent("extproc", "signal_evaluation_failed", map[string]interface{}{
			"request_id": ctx.RequestID,
			"stage":      "authz",
			"error":      authzErr.Error(),
		})
		return nil, authzErr
	}

	signalLatency := time.Since(signalStart).Milliseconds()
	r.applySignalResultsToContext(ctx, signals)
	ensureContextTokenCount(ctx, signalInput)
	logSignalEvaluationResults(ctx, signalLatency, signals)
	tracing.EndSignalSpan(signalSpan, collectMatchedSignalRules(signals), 1.0, signalLatency)
	ctx.TraceContext = signalCtx
	return signals, nil
}

func ensureContextTokenCount(ctx *RequestContext, signalInput signalEvaluationInput) {
	if ctx == nil {
		return
	}
	text := contextTokenText(signalInput)
	if text == "" {
		return
	}
	if ctx.VSRContextTextBytes <= 0 {
		ctx.VSRContextTextBytes = len(text)
	}
	if ctx.VSRContextTokenCount > 0 {
		return
	}
	counter := classification.CharacterBasedTokenCounter{}
	count, err := counter.CountTokens(text)
	if err != nil || count <= 0 {
		return
	}
	ctx.VSRContextTokenCount = count
}

func contextTokenText(signalInput signalEvaluationInput) string {
	text := strings.TrimSpace(signalInput.allMessagesText)
	if text == "" {
		text = strings.TrimSpace(signalInput.evaluationText)
	}
	return text
}

func logSignalEvaluationResults(ctx *RequestContext, signalLatencyMs int64, signals *classification.SignalResults) {
	logging.ComponentDebugEvent("extproc", "signal_evaluation_complete", map[string]interface{}{
		"request_id":     ctx.RequestID,
		"latency_ms":     signalLatencyMs,
		"keyword":        signals.MatchedKeywordRules,
		"embedding":      signals.MatchedEmbeddingRules,
		"domain":         signals.MatchedDomainRules,
		"fact_check":     signals.MatchedFactCheckRules,
		"user_feedback":  signals.MatchedUserFeedbackRules,
		"reask":          signals.MatchedReaskRules,
		"preference":     signals.MatchedPreferenceRules,
		"language":       signals.MatchedLanguageRules,
		"context":        signals.MatchedContextRules,
		"structure":      signals.MatchedStructureRules,
		"complexity":     signals.MatchedComplexityRules,
		"modality":       signals.MatchedModalityRules,
		"authz":          signals.MatchedAuthzRules,
		"jailbreak":      signals.MatchedJailbreakRules,
		"pii":            signals.MatchedPIIRules,
		"kb":             signals.MatchedKBRules,
		"conversation":   signals.MatchedConversationRules,
		"event":          signals.MatchedEventRules,
		"metadata":       signals.MatchedMetadataRules,
		"classifier":     signals.MatchedClassifierRules,
		"projection":     signals.MatchedProjectionRules,
		"context_tokens": signals.TokenCount,
	})
}

func (r *OpenAIRouter) runDecisionEngine(
	originalModel string,
	ctx *RequestContext,
	signals *classification.SignalResults,
	candidates []config.Decision,
) (*decision.DecisionResult, string) {
	// llm_decision_evaluation_latency_seconds and llm_decision_match_total are
	// emitted by decision.DecisionEngine.EvaluateDecisionsWithSignals; do not
	// emit them here or both metrics will be double-counted.
	decisionCtx, decisionSpan := tracing.StartDecisionSpan(ctx.TraceContext, "decision_evaluation")
	classifier := r.classifierForRequest(ctx)
	if classifier == nil {
		logging.ComponentErrorEvent("extproc", "recipe_classifier_unavailable", map[string]interface{}{
			"request_id": ctx.RequestID,
			"recipe":     ctx.Routing.RecipeName(),
		})
		tracing.EndDecisionSpan(decisionSpan, 0.0, []string{}, "")
		ctx.TraceContext = decisionCtx
		return nil, r.defaultModelForUnmatchedDecision(originalModel)
	}
	strategy := classifier.Config.Strategy

	var result *decision.DecisionResult
	var err error
	if candidates != nil {
		if len(candidates) == 0 {
			tracing.EndDecisionSpan(decisionSpan, 0.0, []string{}, string(strategy))
			ctx.TraceContext = decisionCtx
			return nil, r.defaultModelForUnmatchedDecision(originalModel)
		}
		result, err = classifier.EvaluateDecisionWithEngineForDecisions(signals, candidates)
	} else {
		result, err = classifier.EvaluateDecisionWithEngine(signals)
	}
	if err != nil {
		logging.ComponentErrorEvent("extproc", "decision_evaluation_failed", map[string]interface{}{
			"request_id": ctx.RequestID,
			"strategy":   strategy,
			"error":      err.Error(),
		})
		tracing.EndDecisionSpan(decisionSpan, 0.0, []string{}, string(strategy))
		ctx.TraceContext = decisionCtx
		return nil, r.defaultModelForUnmatchedDecision(originalModel)
	}
	if result == nil || result.Decision == nil {
		tracing.EndDecisionSpan(decisionSpan, 0.0, []string{}, string(strategy))
		ctx.TraceContext = decisionCtx
		return nil, r.defaultModelForUnmatchedDecision(originalModel)
	}

	tracing.EndDecisionSpan(decisionSpan, result.Confidence, result.MatchedRules, string(strategy))
	ctx.TraceContext = decisionCtx
	return result, ""
}

func (r *OpenAIRouter) defaultModelForUnmatchedDecision(originalModel string) string {
	if r.requestModelActsAsAuto(originalModel) {
		return r.Config.DefaultModel
	}
	return ""
}

func (r *OpenAIRouter) finalizeDecisionEvaluation(
	result *decision.DecisionResult,
	originalModel string,
	userContent string,
	ctx *RequestContext,
) (string, float64, entropy.ReasoningDecision, string, error) {
	reasoningDecision := entropy.ReasoningDecision{}
	categoryName := r.applyDecisionResultToContext(result, ctx)
	decisionName := result.Decision.Name
	evaluationConfidence := result.Confidence

	ctx.VSRSelectedDecisionConfidence = evaluationConfidence
	logging.ComponentDebugEvent("extproc", "decision_evaluated", map[string]interface{}{
		"request_id":    ctx.RequestID,
		"decision":      decisionName,
		"category":      categoryName,
		"confidence":    evaluationConfidence,
		"matched_rules": result.MatchedRules,
	})

	if !r.requestModelActsAsAuto(originalModel) {
		logging.ComponentDebugEvent("extproc", "explicit_model_preserved", map[string]interface{}{
			"request_id":     ctx.RequestID,
			"original_model": originalModel,
			"decision":       decisionName,
		})
		return decisionName, evaluationConfidence, reasoningDecision, "", nil
	}

	selectedModel, reasoningDecision, err := r.selectDecisionRuntimeModel(
		result,
		decisionName,
		userContent,
		categoryName,
		evaluationConfidence,
		ctx,
	)
	return decisionName, evaluationConfidence, reasoningDecision, selectedModel, err
}

func (r *OpenAIRouter) applyDecisionResultToContext(result *decision.DecisionResult, ctx *RequestContext) string {
	ctx.VSRSelectedDecision = result.Decision
	if pluginCfg := r.Config.EffectiveRouterReplayConfig(result.Decision); pluginCfg != nil {
		ctx.RouterReplayPluginConfig = pluginCfg
	}

	// Snapshot the retention directive emitted by this decision (deep clone)
	// and observe every declared field via log + trace. Both helpers are
	// no-ops when the decision did not emit a retention block.
	applyEmittedRetention(result.Decision, ctx)
	observeRetentionDirective(ctx)

	categoryName := extractDecisionCategory(result.MatchedRules)
	ctx.VSRSelectedCategory = categoryName
	return categoryName
}

func extractDecisionCategory(matchedRules []string) string {
	for _, rule := range matchedRules {
		if strings.HasPrefix(rule, "domain:") {
			return strings.TrimPrefix(rule, "domain:")
		}
	}
	return ""
}

func (r *OpenAIRouter) selectDecisionRuntimeModel(
	result *decision.DecisionResult,
	decisionName string,
	userContent string,
	categoryName string,
	evaluationConfidence float64,
	ctx *RequestContext,
) (string, entropy.ReasoningDecision, error) {
	if len(result.Decision.ModelRefs) == 0 {
		selectedModel := r.Config.DefaultModel
		ctx.VSRSelectedModel = selectedModel
		ctx.VSRSelectionMethod = "default"
		logging.ComponentDebugEvent("extproc", "decision_model_defaulted", map[string]interface{}{
			"request_id":     ctx.RequestID,
			"decision":       decisionName,
			"selected_model": selectedModel,
		})
		return selectedModel, entropy.ReasoningDecision{}, nil
	}
	if result.Decision.GetFastResponseConfig() != nil {
		selectedModel := firstDecisionModelName(result.Decision.ModelRefs)
		if selectedModel == "" {
			selectedModel = r.Config.DefaultModel
		}
		ctx.VSRSelectedModel = selectedModel
		ctx.VSRSelectionMethod = "fast_response"
		return selectedModel, entropy.ReasoningDecision{}, nil
	}

	selCtx := r.buildSelectionContext(
		result.Decision.ModelRefs,
		decisionName,
		userContent,
		result.Decision.Algorithm,
		categoryName,
		result.Decision.CandidateIterations,
		ctx,
	)
	selectedModelRef, usedMethod, err := r.selectModelFromCandidates(
		selCtx,
		result.Decision.Algorithm,
		ctx,
	)
	if err != nil {
		return "", entropy.ReasoningDecision{}, err
	}
	if selectedModelRef == nil {
		selectedModel := r.Config.DefaultModel
		ctx.VSRSelectedModel = selectedModel
		ctx.VSRSelectionMethod = "default"
		logging.Warnf("[ModelSelection] No valid decision modelRefs for decision %s, using default model %s", decisionName, selectedModel)
		return selectedModel, entropy.ReasoningDecision{}, nil
	}
	selectedModel := selectedModelRef.Model
	selectionFields := map[string]interface{}{
		"request_id":        ctx.RequestID,
		"decision":          decisionName,
		"selected_model":    selectedModelRef.Model,
		"selection_method":  usedMethod,
		"uses_lora_adapter": selectedModelRef.LoRAName != "",
	}
	if selectedModelRef.LoRAName != "" {
		selectedModel = selectedModelRef.LoRAName
		selectionFields["selected_model"] = selectedModel
		selectionFields["base_model"] = selectedModelRef.Model
	}
	logging.ComponentDebugEvent("extproc", "decision_model_selected", selectionFields)
	ctx.VSRSelectedModel = selectedModel
	ctx.VSRSelectionMethod = usedMethod
	return selectedModel, applyReasoningModeFromSelectedModel(
		selectedModelRef,
		decisionName,
		evaluationConfidence,
		ctx,
	), nil
}

func firstDecisionModelName(modelRefs []config.ModelRef) string {
	for _, modelRef := range modelRefs {
		if model := strings.TrimSpace(modelRef.LoRAName); model != "" {
			return model
		}
		if model := strings.TrimSpace(modelRef.Model); model != "" {
			return model
		}
	}
	return ""
}

func applyReasoningModeFromSelectedModel(
	selectedModelRef *config.ModelRef,
	decisionName string,
	evaluationConfidence float64,
	ctx *RequestContext,
) entropy.ReasoningDecision {
	if selectedModelRef.UseReasoning == nil {
		return entropy.ReasoningDecision{}
	}

	useReasoning := *selectedModelRef.UseReasoning
	if useReasoning {
		ctx.VSRReasoningMode = "on"
	} else {
		ctx.VSRReasoningMode = "off"
	}

	return entropy.ReasoningDecision{
		UseReasoning:     useReasoning,
		Confidence:       evaluationConfidence,
		DecisionReason:   "decision_engine_evaluation",
		FallbackStrategy: "decision_based_routing",
		TopCategories: []entropy.CategoryProbability{
			{
				Category:    decisionName,
				Probability: float32(evaluationConfidence),
			},
		},
	}
}

